INSERT INTO `tbl_about_us` (`id`, `title`, `content`, `image`, `edited_by`, `created_at`, `updated_at`) VALUES
(1, 'hero_about_img', '', 'Hero.jpg', 0, '2025-12-17 17:13:19', '2026-01-22 19:41:33'),
(2, 'header', 'Line Seiki Asia Pacific Inc.', NULL, 0, '2025-12-17 17:13:19', '2026-01-22 19:41:33'),
(3, 'header_text', 'At Line Seiki Asia Pacific, Inc. (LSA), we bridge innovation from Japan to industries across the Asia-Pacific region. As the official sales arm of Line Seiki Co., Ltd., we bring decades of expertise in measurement technology, automation, and smart manufacturing solutions closer to our partners and customers.', NULL, 0, '2025-12-17 17:13:19', '2026-01-22 19:41:33'),
(4, 'concept_header_1', '1999', NULL, 0, '2025-12-17 17:13:19', '2026-01-05 05:57:44'),
(5, 'concept_header_2', '+40', NULL, 0, '2025-12-17 17:13:19', '2026-01-05 05:57:44'),
(6, 'concept_header_3', '4', NULL, 0, '2025-12-17 17:13:19', '2026-01-05 05:57:44'),
(7, 'concept_header_4', '70+', NULL, 0, '2025-12-17 17:13:19', '2026-01-05 05:57:44'),
(8, 'concept_label_1', 'Year Established', NULL, 0, '2025-12-17 17:15:12', '2026-01-05 05:57:44'),
(9, 'concept_label_2', 'Global Distributor', NULL, 0, '2025-12-17 17:15:12', '2026-01-05 05:57:44'),
(10, 'concept_label_3', 'Regional Offices', NULL, 0, '2025-12-17 17:15:12', '2026-01-05 05:57:44'),
(11, 'concept_label_4', 'Expertise in Measuring & Industrial Solutions', NULL, 0, '2025-12-17 17:15:12', '2026-01-05 05:57:44'),
(12, 'section_header_1', 'Our Regional Commitment', NULL, 0, '2025-12-17 17:18:49', '2026-01-22 19:41:33'),
(13, 'section_header_2', 'Collaboration Across Borders', NULL, 0, '2025-12-17 17:18:49', '2026-01-22 19:41:33'),
(14, 'section_header_3', 'Delivering Reliable Support', NULL, 0, '2025-12-17 17:18:49', '2026-01-22 19:41:33'),
(15, 'section_text_1', 'Connecting Customers and Solutions. We serve as the direct link between Line Seiki Japan and industries across Asia Pacific. From inquiry to delivery, our team ensures that customers receive the right products, technical support, and guidance tailored to their specific applications.', NULL, 0, '2025-12-17 17:18:49', '2026-01-22 19:41:33'),
(16, 'section_text_2', 'Working closely with our headquarters and distributors, we help expand the reach of Line Seiki\'s technologies throughout the region. Through partnerships, training, and joint initiatives, we strengthen communication between engineers, manufacturers, and end users.', NULL, 0, '2025-12-17 17:18:49', '2026-01-22 19:41:33'),
(17, 'section_text_3', 'Our role goes beyond sales — we provide after-sales assistance, technical coordination, and product demonstrations to ensure our customers get lasting value from every Line Seiki solution. By maintaining close collaboration with Japan, we ensure consistent quality and service wherever our customers are.', NULL, 0, '2025-12-17 17:18:49', '2026-01-22 19:41:33'),
(18, 'mission', 'To deliver accurate, reliable, and innovative measurement and monitoring solutions that empower manufacturers to achieve operational excellence and sustainable growth.', NULL, 0, '2025-12-17 17:25:37', '2026-01-22 19:41:33'),
(19, 'vission', 'To be the preferred partner in Southeast Asia for industrial process monitoring, enabling smarter, more connected, and more efficient manufacturing environments.', NULL, NULL, '2025-12-17 17:25:37', '2025-12-17 17:25:37'),
(20, 'partner_header', 'Our Valued Partners & Associations', NULL, 0, '2025-12-17 17:25:37', '2026-01-22 19:41:33'),
(21, 'partner_text', 'We\'re proud to collaborate with industry leaders and organizations that share our commitment to innovation, quality, and excellence in manufacturing technology.', NULL, 0, '2025-12-17 17:25:37', '2026-01-22 19:41:33'),
(22, 'partner_1_img', '', 'MIAP.png', NULL, '2025-12-17 17:25:37', '2025-12-17 17:25:37'),
