INSERT INTO `tbl_achievements` (`id`, `title`, `content`, `year`, `image`, `icon`, `sort_order`, `is_active`, `edited_by`, `created_at`, `updated_at`) VALUES
(1, 'Foundation of Line Seiki', 'Line Seiki established in Tokyo, introducing the first mechanical counter to the Japanese market.', '1955', 'band.png', 'icon-history.png', 1, 1, 0, '2026-03-01 22:50:32', '2026-03-02 01:34:55'),
(2, 'Asia Pacific Headquarters', 'Regional headquarters opened in Singapore, marking the beginning of our expansion into Asia Pacific markets.', '1975', 'band.png', 'icon-globe.png', 2, 1, 0, '2026-03-01 22:50:32', '2026-03-02 01:34:55'),
(3, 'First Electronic Counter', 'Launched our first fully electronic counter, revolutionizing precision measurement in manufacturing.', '1982', 'band.png', 'icon-electronics.png', 3, 1, 0, '2026-03-01 22:50:32', '2026-03-02 01:34:55');
INSERT INTO `tbl_benefits` (`id`, `title`, `description`, `icon`, `created_at`, `updated_at`) VALUES
(1, 'Reduced Cost and Time', 'Minimize physical prototyping and rework through accurate virtual testing.', 'f9a6ac94cd51db9dc27e3552f6808450.png', '2025-12-22 20:41:48', '2026-02-17 23:55:52'),
(2, 'Enhanced Reliability', 'Predict real-world performance and prevent failures before production.', 'verified.png', '2025-12-22 20:41:48', '2026-02-02 12:28:17'),
(3, 'Cost Savings', 'Lower material waste, shorten testing cycles, and reduce overall development expenses through efficient design validation.', 'money.png', '2025-12-22 20:41:48', '2026-02-02 12:28:17');
INSERT INTO `tbl_capabilities` (`id`, `capability_name`, `color_scheme`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Structural & Durability', 'blue', 1, 1, '2026-01-10 04:45:22', '2026-01-26 21:49:05'),
