INSERT INTO `tbl_custom_pages` (`id`, `page`, `data`, `created_at`, `updated_at`) VALUES
(1, 'privacy_policy', '<p><strong>Privacy Policy</strong></p><ul><li>The protection of your personal data is important to Line Seiki. Your personal data will be stored and processed with utmost confidentiality. This privacy policy described below indicates what type of information Line Seiki is permitted to collect and how Line Seiki is to use and protect such data. Please read the following carefully to understand our policy and practices regarding your personal data.</li></ul><h5>1. Personal Data</h5><ul><li>Personal data means any information which we can identify you and include the following.</li></ul><ol><li>Contact Details</li><li>Your name, Postal address, Telephone number and e-mail address</li><li>Technical information collected automatically on our websites</li><li>IP address, Browser type and its version</li><li>Your purchase information</li><li>The amount and date of your purchase, Payment method, Delivery method and delivery address.</li><li>Your communication data</li><li>Your questions, requests and complaints we receive when we communicate with you through telephone and e-mail.</li></ol><h5>2. Purpose Of Personal Data</h5><ul><li>Line Seiki will not collect and use any personal data through our websites, unless this information has been made available to us with your consent. We use personal data that has been made available to us for the purposes below.</li></ul><ol><li>Response to inquiries</li><li>Access to specific information</li><li>Understanding customer needs</li><li>Marketing communication</li><li>Website improvement</li><li>Legal compliance</li></ol><h5>3. Joint Use</h5><ul><li>We share your personal data with the followings.</li></ul><ol><li>Line Seiki Group companies</li><li>Authorized distributors</li><li>Search engine providers</li><li>Third parties for legal requirements</li></ol><h5>4. Retention</h5><ul><li>We share your personal data with the followings.</li></ul><h5>5. Your Rights</h5><ol><li>You have the right to delete Personal data you have provided to us.</li><li>In the event your personal data is processed on the basis of your consent, you can withdraw consent at any time by sending an email to us.</li></ol><h5>6. Security</h5><ul><li>As far as this Website refers to other websites provided by third parties we shall not assume any liability for the contents thereof, nor for their providers\' compliance with the data protection regulations.</li></ul><h5>7. Links To Other Website</h5><ul><li>We take the required precautionary measures to ensure the safety of personal data and continuously strive to improve data integrity. We carefully protect personal data against loss, destruction, falsification, manipulation, or unlawful publication.</li></ul><h5>8. Changes To Policy</h5><ul><li>We reserve the right to make changes, amendments, modifications or cancellations, in whole or in part, of this policy without prior notice at any time. By continuing to use our Website after it has been changed by us, you also agree to accept these changes.</li></ul><h5>9. Contact Us</h5><ul><li>If you have any queries about this Privacy Policy or if you want to exercise your rights, please email us.</li></ul><p><br></p>', NULL, '2026-01-05 11:39:45'),
(2, 'terms_of_service', 'Sample Terms and Services Content', NULL, '2026-01-21 18:52:20'),
(3, 'cookie_settings', 'Cookies Policy \r\n\r\nIt is possible that so-called “cookies” are used on some of Line Seiki’s web pages. A cookie is a small text file that is stored from a Website to your hard disk. All cookies stored from our Website are delated from your hard disk automatically once you close your browser.\r\n\r\n Copyright Information \r\n\r\nCopyright © 2023 Line Seiki Co., Ltd.. All rights reserved.\r\n\r\nThis website uses Google Analytics as an access analysis tool. Google Analytics uses cookies to collect traffic data. The traffic data collected is anonymous so that it does not identify individuals. You can refuse providing the traffic data by invalidating cookie. Please confirm the setting of your browser. For more information, please check Google Analytics Terms of Service.', NULL, '2026-01-21 17:13:09');
