INSERT INTO `tbl_events` (`id`, `title`, `content`, `meta_description`, `category`, `event_date`, `is_featured`, `badge_text`, `status`, `image`, `edited_by`, `created_at`, `updated_at`, `deleted_at`, `is_gated`) VALUES
(1, 'Line Seiki to Exhibit at JAPAN PACK 2025', 'Join us at Tokyo Big Sight as we showcase our latest measuring instruments, sensors, and IoT solutions. Visit booth 5-122 to see live demonstrations and meet our technical experts.', 'Line Seiki exhibition at JAPAN PACK 2025 featuring measuring instruments, sensors, and IoT solutions', 'events', '2026-06-01', 1, 'Featured Event', 'active', 'event1.jpg', 0, '2025-12-26 01:01:34', '2026-02-19 12:41:39', NULL, 1),
(2, 'Introducing Our Next-Gen Safety Switches', 'Discover our latest safety switches and relays designed for smarter, safer manufacturing environments with enhanced durability and reliability.', 'New safety switches and relays from Line Seiki for smarter, safer manufacturing environments', 'product', '2025-08-15', 0, 'New Release', 'active', 'newlaunch1.jpg', 0, '2025-12-26 01:01:34', '2026-01-15 05:58:29', NULL, 0),
(3, 'Line Seiki Announces Strategic Partnership', 'We\'re excited to announce our new partnership with leading automation companies to expand our IoT solutions portfolio across Asia Pacific.', 'Line Seiki announces strategic partnership with automation companies to expand IoT solutions', 'news', '2025-07-28', 1, 'Featured Event', 'active', 'newlaunch4.jpg', 0, '2025-12-26 01:01:34', '2026-01-27 14:07:22', NULL, 0),
(4, 'Smart IoT Solutions for Modern Manufacturing', 'Join our expert-led webinar on integrating smart solutions for seamless operational control and data-driven decision making.', 'Webinar on smart IoT solutions for modern manufacturing and operational control', 'webinars', '2025-09-05', 0, 'Webinar', 'inactive', 'webinar4.jpg', 0, '2025-12-26 01:01:34', '2026-02-21 22:31:38', '2026-02-22 13:31:38', 0),
(5, '2025 Manufacturing Technology Trends', 'Our latest industry report analyzes emerging trends in precision measurement and automation technologies shaping the future of manufacturing.', 'Line Seiki industry report on 2025 manufacturing technology trends and precision measurement', 'news', '2025-06-12', 0, 'Insight', 'active', 'newlaunch3.jpg', NULL, '2025-12-26 01:01:34', '2025-12-26 01:01:34', NULL, 0),
(6, 'Technical Seminar: Advanced Measurement Techniques', 'A series of talks by our engineers on the latest advancements in industrial measurement and precision instruments.', 'Technical seminar on advanced measurement techniques by Line Seiki engineers', 'events', '2026-03-01', 0, 'Seminar', 'active', '405c07a8ffdf77e10a196ad83cc30120.png', 0, '2025-12-26 01:01:34', '2026-01-27 14:22:45', NULL, 0),
(7, 'Line Seiki to exhibit at JAPAN PACK 2025.', 'Line Seiki Co., Ltd. will be exhibiting at JAPAN PACK 2025, Tokyo Japan. We will showcase our latest measuring instruments, sensors, and IoT solutions. JAPAN PACK 2025, Date: October 7 to 10, 2025, Location: Tokyo Big Sight, Booth: 5-122 (East Exhibition Hall E5), Website: https://www.japanpack.jp/en/, Exhibitor Detail: https://www.japanpack.jp/en/exhibitor/detail/?id=161', 'Line Seiki exhibition details for JAPAN PACK 2025 at Tokyo Big Sight with booth information and links', 'events', '2025-10-07', 1, 'Notice', 'active', 'event1.jpg', 0, '2025-12-26 01:01:34', '2026-01-15 05:58:29', NULL, 0),
(8, 'Sample', 'awdawd', 'awdawdawd', 'news', '2026-01-13', 0, 'Sample', 'inactive', 'f2e1b935be8e19c283a03d7c6a53b564.png', 0, '2026-01-19 10:19:41', '2026-01-18 19:40:19', '2026-01-19 10:40:19', 0),
