INSERT INTO `tbl_iotsolution` (`id`, `title`, `content`, `image`, `edited_by`, `created_at`, `updated_at`) VALUES
(1, 'Real-Time Machine Monitoring Title', 'Real-Time Machine Monitoring That Keeps You in Control', 'new-herogemba.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(2, 'Real-Time Machine Monitoring Content', 'No subscription. No fixed cost. Just one setup that keeps you connected.', 'new-herogemba.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(3, 'Our Solution Title', 'Our Solution', 'Machine1.png', NULL, '2025-12-23 02:43:26', '2025-12-23 02:43:26'),
(4, 'Our Solution Problem', 'Manual recording and delayed updates make it difficult to see what\'s really happening on the shop floor.', 'Machine1.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(5, 'Our Solution Content', 'The GEMBA Reporter Machine Monitoring System helps eliminate blind spots by capturing machine data automatically — so you can identify downtime causes, improve efficiency, and make data-driven decisions faster.', 'Machine1.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(6, 'System Setup Diagram', 'System Set-Up Diagram', 'system-setupnobg.png', NULL, '2025-12-23 02:43:26', '2025-12-23 02:43:26'),
(7, 'Gemba Reporter Product Image', 'Gemba Reporter System', 'Gemba-repo.png', NULL, '2025-12-23 02:43:26', '2025-12-23 02:43:26'),
(8, 'Base Station Product', 'Base Station', 'Gemba-repo.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(9, 'Base Station Description', 'Acts as the control hub, receiving and storing data from up to 10 Smart Counters simultaneously. Loaded with Line Seiki\'s in-house software, it organizes the data and performs real-time analysis.', 'Gemba-repo.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(10, 'Smart Counter Product', 'Smart Counter', 'Gemba-repo.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(11, 'Smart Counter Description', 'Mounted directly on your machine, it collects essential data such as production quantity, cycle time, and operating status. It wirelessly transmits all data to the Base Station — no need for complex wiring', 'Gemba-repo.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(12, 'System Setup - Smart Counter', 'Smart Counter', 'system-setupnobg.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(13, 'System Setup - Smart Counter Item 1', 'Counts production', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(14, 'System Setup - Smart Counter Item 2', 'Detects machine up/down status', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(15, 'System Setup - Smart Counter Item 3', 'Sends data wirelessly', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(16, 'System Setup - Smart Counter Item 4', 'One Smart Counter per machine', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(17, 'System Setup - Base Station', 'Base Station', 'system-setupnobg.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(18, 'System Setup - Base Station Item 1', 'Connects with up to 10 machines', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(19, 'System Setup - Base Station Item 2', 'Receives data wirelessly', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(20, 'System Setup - Base Station Item 3', 'Sends data to Data Server via LAN', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(21, 'System Setup - Base Station Item 4', 'Acts as the \"hub\" for a group of machines', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(22, 'System Setup - Factory Network', 'Factory Network', 'system-setupnobg.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(23, 'System Setup - Factory Network Item 1', 'Router/switch connects everything', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(24, 'System Setup - Factory Network Item 2', 'Data Server + Base Stations must use LAN cables', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(25, 'System Setup - Factory Network Item 3', 'Access via PC or tablet on the same network', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(26, 'System Setup - Data Server', 'Data Server', 'system-setupnobg.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(27, 'System Setup - Data Server Item 1', 'Saves all production data', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(28, 'System Setup - Data Server Item 2', 'Shows real-time dashboards', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(29, 'System Setup - Data Server Item 3', 'Runs the GEMBA Reporter software', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(30, 'System Setup - Data Server Item 4', 'Supports up to 12 Base Stations (120 machines)', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(31, 'System Setup - User Device', 'User Device', 'system-setupnobg.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(32, 'System Setup - User Device Item 1', 'No software installation', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(33, 'System Setup - User Device Item 2', 'Works on PC, laptop, or tablet', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(34, 'System Setup - User Device Item 3', 'View machine status, downtime, records, and reports', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(35, 'System Setup - User Device Item 4', 'Export data to Excel with one click', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(36, 'Production Data Title', 'Production Data', NULL, NULL, '2025-12-23 02:43:26', '2025-12-23 02:43:26'),
(37, 'Production Data Description', 'The GEMBA dashboard gives you a comprehensive view of your machine status.', NULL, NULL, '2025-12-23 02:43:26', '2025-12-23 02:43:26'),
(38, 'Production Data - Control Page', 'Control Page', '2xpage-nobg.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(39, 'Production Data - Control Page Content', 'Input and monitor essential machine job details in one place.', '2xpage-nobg.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(40, 'Production Data - Count Dashboard', 'Count Dashboard', 'countdash.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(41, 'Production Data - Count Dashboard Content', 'Track actual output versus target quantity for every machine. Easily visualize progress percentages and ensure production goals are being met in real time.', 'countdash.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(42, 'Production Data - Duration Dashboard', 'Duration Dashboard', 'duration.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(43, 'Production Data - Duration Dashboard Content', 'This page shows the running time and downtime of multiple machines. You can easily see how long each machine has been working or idle.', 'duration.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(44, 'Production Data - Overview', 'Overview', 'overview.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(45, 'Production Data - Overview Content', 'Gives you a quick snapshot of all machines in one view — making it easy to check the overall production status at a glance.', 'overview.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(46, 'Make Informed Decisions Title', 'Make Informed Decisions', NULL, NULL, '2025-12-23 02:43:26', '2025-12-23 02:43:26'),
(47, 'Feature - Real-Time Visibility', 'Real-Time Visibility', 'eye.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(48, 'Feature - Real-Time Visibility Content', 'Instantly know which machines are running or idle.', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(49, 'Feature - Wireless Installation', 'Wireless Installation', 'wifi.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(50, 'Feature - Wireless Installation Content', 'Quick setup, minimal disruption to existing machines.', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
