(52, 'Feature - Scalable Content', 'Easily expand your setup by connecting up to 10 Smart Counters per Base Station.', NULL, 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
(53, 'Feature - Automated Records', 'Automated Records', 'google-docs.png', 0, '2025-12-23 02:43:26', '2026-03-02 12:12:37'),
