INSERT INTO `tbl_privacy_policy` (`id`, `title`, `content`, `image`, `edited_by`, `created_at`, `updated_at`) VALUES
(1, 'Privacy Policy Introduction', 'The protection of your personal data is important to Line Seiki. Your personal data will be stored and processed with utmost confidentiality. This privacy policy described below indicates what type of information Line Seiki is permitted to collect and how Line Seiki is to use and protect such data. Please read the following carefully to understand our policy and practices regarding your personal data.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:53:56'),
(2, 'Personal Data Definition', 'Personal data means any information which we can identify you and include the following.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(3, 'Contact Details', 'Your name, Postal address, Telephone number and e-mail address', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(4, 'Technical information collected automatically on our websites', 'IP address, Browser type and its version', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(5, 'Your purchase information', 'The amount and date of your purchase, Payment method, Delivery method and delivery address.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(6, 'Your communication data', 'Your questions, requests and complaints we receive when we communicate with you through telephone and e-mail.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(7, 'Purpose Of Personal Data Introduction', 'Line Seiki will not collect and use any personal data through our websites, unless this information has been made available to us with your consent. We use personal data that has been made available to us for the purposes below.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(8, 'Purpose 1 - Response to inquiries', 'In order to ensure response to your inquiries or complaints and handle your purchase orders and requests.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(9, 'Purpose 2 - Access to specific information', 'In order to ensure access to specific information.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(10, 'Purpose 3 - Understanding customer needs', 'In order to a better understand of your needs and requirements and so to improve our products and services.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(11, 'Purpose 4 - Marketing communication', 'In order to contact you and provide you with information and offers.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(12, 'Purpose 5 - Website improvement', 'In order to improve our websites.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(13, 'Purpose 6 - Legal compliance', 'In order to comply with lawful requests by public authorities.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(14, 'Joint Use Introduction', 'We share your personal data with the followings.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(15, 'Joint Use - Line Seiki Group companies', 'Line Seiki Group companies', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(16, 'Joint Use - Authorized distributors', 'Our authorized distributors', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(17, 'Joint Use - Search engine providers', 'Search engine providers such as Google Analytics', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(18, 'Joint Use - Third parties for legal requirements', 'Third parties in case of legal requirement', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(19, 'Retention', 'We share your personal data with the followings.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(20, 'Your Rights - Deletion right', 'You have the right to delete Personal data you have provided to us.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(21, 'Your Rights - Consent withdrawal', 'In the event your personal data is processed on the basis of your consent, you can withdraw consent at any time by sending an email to us.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(22, 'Security', 'As far as this Website refers to other websites provided by third parties we shall not assume any liability for the contents thereof, nor for their providers\' compliance with the data protection regulations.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(23, 'Links To Other Website', 'We take the required precautionary measures to ensure the safety of personal data and continuously strive to improve data integrity. We carefully protect personal data against loss, destruction, falsification, manipulation, or unlawful publication.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(24, 'Changes To Policy', 'We reserve the right to make changes, amendments, modifications or cancellations, in whole or in part, of this policy without prior notice at any time. By continuing to use our Website after it has been changed by us, you also agree to accept these changes.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10'),
(25, 'Contact Us', 'If you have any queries about this Privacy Policy or if you want to exercise your rights, please email us.', NULL, NULL, '2026-01-01 18:40:10', '2026-01-01 18:40:10');
