INSERT INTO `tbl_product_items` (`id`, `product_category`, `product_type`, `product_name`, `series_name`, `sub_title`, `slug`, `model_number`, `description`, `short_description`, `product_image`, `dimensions_image`, `contact_configuration_image`, `gallery_images`, `features`, `specifications`, `operating_distances`, `complied_standards`, `models_data`, `applications`, `applications_data`, `related_products`, `tags`, `video_url`, `youtube_embed`, `brochure_pdf`, `manual_pdf`, `datasheet_pdf`, `cad_files`, `downloads_data`, `price`, `currency`, `stock_status`, `meta_title`, `meta_description`, `meta_keywords`, `display_order`, `is_active`, `is_featured`, `is_new`, `created_at`, `updated_at`, `created_by`, `updated_by`) VALUES
(1, 1, 1, 'SS2-P-1 Series', 'SS2-P-1 series', 'Non-contact Safety Switch', 'ss2-p-1-series', 'SS2-P-112', 'PLd per ISO 13849-1 in stand-alone applications. Cross monitoring between two channels. Multiple units can be connected to one safety relay unit.', 'Non-contact safety switch with PLd rating', 'product_1768986843497_ben9pj_ss2_p1_series.jpg', NULL, NULL, NULL, 'PLd per ISO 13849-1 in stand-alone applications\r\nCross monitoring between two channels\r\nMultiple units can be connected to one safety relay unit', 'Power Supply Voltage: DC24V (-15%/+10%)\r\nOperating Distdddances: Rated Operating Distance: 12mm, Assured Switch ON Distance: 10mm, Assured Switch OFF Distance: 15mm, Hysteresis: 2mm, Repeat Accuracy: <5%\r\nSafety Output Protection: Internal Fuse 2A\r\nOperating Temperature: -25 – +60°C\r\nType Coding Level (ISO 14119): 4 / Low\r\nMTTFd: >100 years\r\nComplied Standards: ISO 13849-1, ISO 14119, IEC 60204-1, IEC 61508-1, IEC 61508-2, IEC 62061, IEC 60947-5-3, UL 60947-1, UL 60947-5-2, CSA C22.2 No. 60947-1, CSA C22.2 No. 60947-5-2, CE, RoHS\r\nSample: Sample Data', 'Rated Operating Distance: 12mm\nAssured Switch ON Distance: 10mm\nAssured Switch OFF Distance: 15mm\nHysteresis: 2mm\nRepeat Accuracy: <5%', 'ISO 13849-1, ISO 14119, IEC 60204-1, IEC 61508-1, IEC 61508-2, IEC 62061, IEC 60947-5-3, UL 60947-1, UL 60947-5-2, CSA C22.2 No. 60947-1, CSA C22.2 No. 60947-5-2, CE, RoHS', '[]', NULL, '[{\"title\":\"Door of Food Processing Machinery\",\"badge\":\"Safety\",\"link\":\"\",\"image\":\"application_1768621754358_u1qo8p_Burgerking.png\"},{\"title\":\"Semiconductor Material Handling System\",\"badge\":\"Safety\",\"link\":\"\",\"image\":\"37.jpg\"},{\"title\":\"Door of Semiconductor Equipment\",\"badge\":\"Safety\",\"link\":\"\",\"image\":\"1a41e13a1ea34d1945c61cc663c5a85f.png\"}]', NULL, 'Plastic,Stand-alone', 'https://youtu.be/nNI2By9m0hI', 'nNI2By9m0hI', NULL, NULL, NULL, NULL, '[{\"label\":\"Catalog(EN)\",\"url\":\"https://www.lineseiki.com/wp-content/uplo