(2, 'hero_description', 'We help engineers and manufacturers reduce design errors, speed up development, and bring better products to market—through virtual testing and engineering simulation.', NULL, NULL, '2025-12-22 20:41:48', '2026-02-21 18:52:32'),
(3, 'hero_image', NULL, 'simul1bg.png', NULL, '2025-12-22 20:41:48', '2026-02-21 18:52:32'),
(4, 'consultation_button', 'Schedule a Consultation', NULL, NULL, '2025-12-22 20:41:48', '2025-12-22 20:41:48'),
(5, 'what_we_do_title', 'What We Do', NULL, NULL, '2025-12-22 20:41:48', '2025-12-22 20:41:48'),
(6, 'what_we_do_text', 'Line Seiki offers Computer-Aided Engineering (CAE) Simulation Analysis services that help manufacturers and product designers evaluate performance, reliability, and safety—before physical prototyping begins.\r\n\r\nThrough advanced simulation and virtual testing, our engineers analyze factors such as stress, heat, vibration, and fatigue to predict how a design will behave under real-world conditions. Backed by decades of engineering experience and a strong foundation in manufacturing, Line Seiki supports industries such as automotive, semiconductor, consumer electronics, and general manufacturing in achieving smarter, data-driven product development.', NULL, NULL, '2025-12-22 20:41:48', '2026-02-21 18:52:32'),
(7, 'capabilities_title', 'Our Capabilities', NULL, NULL, '2025-12-22 20:41:48', '2025-12-22 20:41:48'),
