INSERT INTO `tbl_simulation_carousel` (`id`, `title`, `abstract`, `main_image`, `link`, `content_id`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Structural Analysis of a Gear Jig During Process Setupwdwdwdw', 'This study presents a structural contact stress analysis to investigate part deformation and gear–jig interaction during process setup. The simulation identified zones of excessive local stress, guiding jig redesign and eliminating repeated fabrications.', 'cs1.png', 'Structural Analysis of a Gear Jig During Process Setupwdwdwdw', 3, 1, 1, '2026-01-10 08:15:02', '2026-02-21 03:50:40'),
(2, 'Buckling Analysis of a Consumer Electronics Enclosure', 'This analysis evaluates the stability of an enclosure cover under elevated temperature. Simulation predicted deformation and compared thickness and rib options, enabling optimal geometry and faster proof-of-concept.', 'cs2.png', 'Buckling Analysis of a Consumer Electronics Enclosure', 2, 2, 1, '2026-01-10 08:15:02', '2026-02-21 03:50:40'),
(3, 'Transient Thermal Analysis of a PCB Heatsink Design', 'This project simulated transient heat dissipation in a PCB assembly. The study optimized heatsink type and placement virtually, reducing re spins and enabling earlier product release.', '7912cb326e90313c21691755077fb7cc.png', 'Transient Thermal Analysis of a PCB Heatsink Design', 1, 3, 1, '2026-01-11 17:03:19', '2026-02-21 03:50:40');
INSERT INTO `tbl_simulation_content` (`id`, `title`, `main_image`, `abstract`, `client`, `problem`, `study`, `analysis_type`, `root_cause`, `solution`, `prototype_without`, `prototype_with`, `prototype_reduction`, `testing_without`, `testing_with`, `testing_reduction`, `development_without`, `development_with`, `development_reduction`, `qualitative_benefits`, `actual_image_filename`, `simulation_image_filename`, `created_at`, `updated_at`) VALUES
(1, 'Structural Analysis of a Gear Jig During Process Setup', 'cs1.png', 'This study presents a structural contact stress analysis to investigate part deformation and gear–jig interaction during process setup. The simulation identified zones of excessive local stress, guiding jig redesign and eliminating repeated fabrications.', 'Manufacturing', 'Part deformation during process setup', 'Simulate process and gear–jig contact', 'Contact Stress', 'Damage gear tooth due to excessive local stress', 'Simulation identified the high contact stress zones, guiding jig redesign and cutting repeated fabrications.', '$720', '$90', '-88%', '$2,496', '$936', '-63%', '12 weeks', '3 weeks', '-75%', 'Prevent shipment delays & potential customer loss.', 'image3.png', 'image4.png', '2026-02-13 02:20:21', '2026-02-21 21:55:46'),
(2, 'Buckling Analysis of a Consumer Electronics Enclosure', 'cs2.png', 'This analysis evaluates the stability of an enclosure cover under elevated temperature. Simulation predicted deformation and compared thickness and rib options, enabling optimal geometry and faster proof-of-concept.', 'Consumer Electronics', 'Enclosure cover instability at high temperature', 'Perform geometry optimization', 'Buckling', 'Insufficient thickness and lack of reinforcement', 'Simulation predicted deformation and compared thickness/rib options, enabling optimum design.', '$2,234', '$500', '-78%', '$2,016', '$888', '-56%', '10 weeks', '2 weeks', '-80%', 'Accelerated proof-of-concept to stay ahead of competitors.', 'cs1.png', 'cs1.png', '2026-02-13 02:20:43', '2026-02-21 02:43:49'),
(3, 'Transient Thermal Analysis of a PCB Heatsink Design', '7912cb326e90313c21691755077fb7cc.png', 'This project simulated transient heat dissipation in a PCB assembly. The study optimized heatsink type and placement virtually, reducing re spins and enabling earlier product release.', 'ManufacElectronicsturing', 'Overheating and repeated trial-and-error in PCB design', 'Perform transient thermal analysis of heat dissipation', 'Transient Thermal', 'Inefficient heatsink type and placement', 'Simulation optimized heatsink design and placement virtually, enabling quick iteration and avoiding PCB re-spins.', '$1,515', '$610', '-60%', '$3,640', '$1,300', '-64%', '6 weeks', '2 weeks', '-67%', 'Earlier product release in consumer electronics market.', 'IMG_4336.jpg', 'image8.png', '2026-02-13 23:17:21', '2026-02-21 02:44:00');
INSERT INTO `tbl_smuc` (`id`, `title`, `content`, `image`, `edited_by`, `created_at`, `updated_at`) VALUES
(1, 'hero_title', 'Production Quality at Low Volumes', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(2, 'hero_description', 'Get full-scale aesthetics and performance without fullscale tooling. Silicone Molding and Urethane Casting deliver production-grade parts for concept, validation and low-volume runs.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(3, 'hero_image', NULL, '1768203591_sm4.png', NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(4, 'hero_button', 'Request a Quote', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(5, 'what_we_do_title', 'WHAT DO WE DO', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(6, 'what_we_do_subtitle', 'Precision-crafted parts through Silicone Molding and Urethane Casting.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(7, 'silicone_mold_title', 'Silicone Molding', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(8, 'silicone_mold_description', 'Flexible, high-detail molds that capture even the most intricate surface textures.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(9, 'urethane_part_title', 'Urethane Part', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(10, 'urethane_part_description', 'Durable, functional, and production-grade.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(11, 'illustration_top_mold', NULL, 'sm1.png', NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(12, 'illustration_internal_part', NULL, 'sm2.png', NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(13, 'illustration_bottom_mold', NULL, 'sm3.png', NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(14, 'silicone_molding_title', 'Silicone Molding', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(15, 'silicone_molding_content', 'Silicone molding—also known as Room Temperature Vulcanizing (RTV) molding—uses a flexible silicone mold to reproduce parts with exceptional surface detail and accuracy. It\'s the ideal process for creating small-batch or low-volume parts without the high investment cost of injection molding or press dies.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(17, 'silicone_molding_feature_1', 'Produces up to 10–50 parts per mold, depending on design and material.', NULL, 0, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(18, 'silicone_molding_feature_2', 'Captures fine surface textures — even details as small as fingerprint marks.', NULL, 0, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(19, 'silicone_molding_feature_3', 'Supports insert molding and over-molding applications.', NULL, 0, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(20, 'silicone_molding_feature_4', 'Maximum casting size: 450 × 450 × 450 mm.', NULL, 0, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(21, 'silicone_molding_feature_5', 'Minimum guaranteed wall thickness: 1.5 mm.', NULL, 0, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(22, 'urethane_casting_title', 'Urethane Casting', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(23, 'urethane_casting_content', 'Urethane casting uses thermosetting polyurethane resins—similar to epoxy—to produce multiple copies of your master model. Combined with silicone molds, this process delivers high-detail prototypes and functional parts that can match the look, feel, and performance of injection-molded products.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(25, 'urethane_casting_feature_1', 'Tight dimensional tolerance of ±0.15 mm per 100 mm.', NULL, 0, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(26, 'urethane_casting_feature_2', 'Fine feature replication down to 0.5 mm width and depth.', NULL, 0, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(27, 'urethane_casting_feature_3', 'Cast-in color options (blue, green, yellow, red) to reduce post-painting time.', NULL, 0, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(28, 'urethane_casting_feature_4', 'Supports post-processing such as machining, painting, and assembly.', NULL, 0, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(29, 'urethane_casting_feature_5', 'UL- and RoHS-compliant materials available.', NULL, 0, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(30, 'urethane_casting_feature_6', 'Suitable for final product components and functional testing.', NULL, 0, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(31, 'urethane_casting_feature_7', 'More cost-efficient than 3D printing for quantities above 10 pcs.', NULL, 0, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(32, 'urethane_casting_feature_8', 'Ideal alternative to injection molding for runs under 1,000 pcs.', NULL, 0, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(33, 'process_step_1_title', 'Silicone Molding', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(34, 'process_step_1_description', 'Liquid silicone is poured around the master pattern to form a flexible mold.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(35, 'process_step_1_image', NULL, 'sm9.png', NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(36, 'process_step_2_title', 'Mold Removal', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(37, 'process_step_2_description', 'The cured silicone mold is carefully cut and separated from the master pattern.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(38, 'process_step_2_image', NULL, 'sm6.png', NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(39, 'process_step_3_title', 'Urethane Casting', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(40, 'process_step_3_description', 'Urethane resin is poured into the silicone mold to replicate the master part.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(41, 'process_step_3_image', NULL, 'sm7.png', NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(42, 'process_step_4_title', 'Copies of Prototype', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(43, 'process_step_4_description', 'Multiple casted parts are produced with high accuracy and surface detail.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(44, 'process_step_4_image', NULL, 'sm8.png', NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(45, 'gallery_title', NULL, NULL, NULL, '2025-12-22 22:55:21', '2026-01-12 13:43:42'),
(46, 'gallery_subtitle', NULL, NULL, NULL, '2025-12-22 22:55:21', '2026-01-12 13:43:42'),
(47, 'gallery_tab_1', NULL, NULL, NULL, '2025-12-22 22:55:21', '2026-01-12 13:43:42'),
(48, 'gallery_tab_2', NULL, NULL, NULL, '2025-12-22 22:55:21', '2026-01-12 13:43:42'),
(49, 'wcu_subtitle', 'Our Advantage', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(50, 'wcu_title', 'Why Choose Line Seiki?', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(51, 'wcu_description', 'Combining Japanese precision engineering with rapid prototyping agility to deliver superior results.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(52, 'wcu_card_1_title', 'Fast Turnaround', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(53, 'wcu_card_1_description', 'From master pattern to finished parts in days. We accelerate your time-to-market.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(54, 'wcu_card_2_title', 'Injection Quality', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(55, 'wcu_card_2_description', 'Achieve production-grade detail and texture without expensive steel tooling.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(56, 'wcu_card_3_title', 'Cost Efficiency', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(57, 'wcu_card_3_description', 'Silicone molds cost a fraction of metal tooling, making small runs highly profitable.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(58, 'wcu_card_4_title', 'Material Variety', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(59, 'wcu_card_4_description', 'Access a wide range of polymers, rubber-likes, and rigid engineering plastics.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(60, 'wcu_video', NULL, 'Facility Tour.mp4', NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(61, 'benefits_title', 'The Benefits of SMUC', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(62, 'benefits_subtitle', 'Silicone Molding & Urethane Casting (SMUC) bridges the gap between prototyping and mass production.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(63, 'benefit_1_number', '01', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(64, 'benefit_1_title', 'Low-Volume, High Quality', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(65, 'benefit_1_description', 'Whether you need 5 or 100 pieces, benefit from production-grade look and feel.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(66, 'benefit_1_image', NULL, 'SMUC2.jpg', NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(67, 'benefit_2_number', '02', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(68, 'benefit_2_title', 'Market Validation & Testing', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(69, 'benefit_2_description', 'Use realistic parts to conduct user testing, refine design and iterate before committing to full production.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(70, 'benefit_2_image', NULL, 'SMUC3.jpg', NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(71, 'benefit_3_number', '03', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(72, 'benefit_3_title', 'Cost Efficiency', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(73, 'benefit_3_description', 'Avoid high upfront tooling costs and pay only for what you need, when you need it.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(74, 'benefit_3_image', NULL, 'SMUC4.jpg', NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(75, 'benefit_4_number', '04', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(76, 'benefit_4_title', 'Rapid Iteration', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(77, 'benefit_4_description', 'Our process supports quick changes refine your design and re-cast faster than with traditional tooling.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(78, 'benefit_4_image', NULL, 'SMUC1.jpg', NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(79, 'iso_title', 'Our Commitment to Quality', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(80, 'iso_subtitle', 'ISO 9001:2015 Certified for Excellence', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
(81, 'iso_description', 'At Line Seiki Asia Pacific, quality is at the heart of everything we do. Our ISO 9001:2015 certification demonstrates our unwavering commitment to providing products and services that consistently meet customer and regulatory requirements. We are dedicated to continuous improvement, ensuring that our processes are efficient, reliable, and focused on delivering the highest level of satisfaction.', NULL, NULL, '2025-12-22 22:55:21', '2026-02-18 12:44:51'),
