INSERT INTO `tbl_testimonial` (`id`, `name`, `position`, `content`, `image`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'James Wong', 'Engineering Manager, TechPrecise', 'Line Seiki’s simulation analysis helped us cut prototyping costs by 30% and accelerated our time-to-market significantly. Their team’s expertise in CAE is exceptional.', 'man.png', 1, 1, '2026-03-02 00:54:53', '2026-03-02 01:08:22'),
(2, 'Dr. Ananya Sharma', 'R&D Lead, AeroInnovate', 'The thermal and structural simulations provided deep insights that physical testing alone could not achieve. Highly professional and reliable partner.', 'man.png', 2, 1, '2026-03-02 00:54:53', '2026-03-02 01:08:22'),
(3, 'Michael Chen', 'Product Designer, FormFab', 'We were impressed by the accuracy of the FEA results. The detailed report and recommendations made design optimization straightforward.', 'man.png', 3, 1, '2026-03-02 00:54:53', '2026-03-02 03:26:51'),
(4, 'Siti Nurhaliza', 'Operations Director, M&E Solutions', 'Outstanding service from start to finish. The team understood our requirements perfectly and delivered actionable simulation data.', 'man.png', 4, 0, '2026-03-02 00:54:53', '2026-03-02 04:15:08');
