INSERT INTO `tbl_webinar` (`id`, `webinar_title`, `main_image`, `description_1`, `description_2`) VALUES
(1, 'Advanced Injection Molding Techniques', 'newsim4.png', 'Learn advanced techniques for injection molding optimization, including temperature control, pressure management, and cycle time reduction. This webinar is perfect for experienced engineers looking to enhance their manufacturing processes.', 'Key topics covered: - Optimal temperature settings for different materials - Pressure management strategies - Cycle time reduction techniques - Common defects and how to prevent them - Q&A session with industry experts'),
(2, 'IoT Solutions for Smart Manufacturing', 'webinar-iot-manufacturing.jpg', 'Discover how Internet of Things (IoT) technology is transforming the manufacturing landscape. This webinar explores practical applications of IoT in production environments, from real-time monitoring to predictive maintenance.', 'Webinar highlights: - Introduction to Industrial IoT (IIoT) - Real-time production monitoring systems - Predictive maintenance strategies - Data analytics for process optimization - Case studies from successful implementations - Future trends in smart manufacturing'),
(3, 'Precision Engineering: Best Practices', 'webinar-precision-engineering.jpg', 'Join our precision engineering experts as they share best practices for achieving high-accuracy results in manufacturing. Learn about tolerance management, quality control, and advanced measurement techniques.', 'Topics covered: - Understanding and managing tolerances - Advanced measurement and inspection methods - Quality control best practices - Surface finish optimization - Material selection for precision parts - Real-world examples and case studies');
