  CONSTRAINT `tbl_capability_items_ibfk_1` FOREIGN KEY (`capability_id`) REFERENCES `tbl_capabilities` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

DROP TABLE IF EXISTS `tbl_card_categories`;
