  `image` varchar(255) DEFAULT NULL,
  `pdf_file` varchar(255) DEFAULT NULL,
  `video_url` varchar(500) DEFAULT NULL,
  `file_type` varchar(50) DEFAULT NULL,
  `edited_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `is_gated` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `tbl_partners`;
CREATE TABLE `tbl_partners` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `partner_name` varchar(255) NOT NULL,
  `partner_logo` varchar(255) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

DROP TABLE IF EXISTS `tbl_privacy_policy`;
CREATE TABLE `tbl_privacy_policy` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `content` longtext NOT NULL,
  `image` varchar(255) DEFAULT NULL,
  `edited_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `tbl_product_applications`;
CREATE TABLE `tbl_product_applications` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) DEFAULT NULL COMMENT 'FK to tbl_product_items (NULL for shared)',
  `category_id` int(11) DEFAULT NULL COMMENT 'FK to tbl_product_category (NULL for any)',
  `title` varchar(255) NOT NULL COMMENT 'Application title',
  `description` text DEFAULT NULL COMMENT 'Application description',
  `image` varchar(255) DEFAULT NULL COMMENT 'Application image',
  `badge_text` varchar(50) DEFAULT NULL COMMENT 'Badge label',
  `link_url` varchar(500) DEFAULT NULL COMMENT 'Link to full case study',
  `display_order` int(11) DEFAULT 0 COMMENT 'Sort order',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '1=active, 0=inactive',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`),
  KEY `category_id` (`category_id`),
  KEY `is_active` (`is_active`),
  KEY `display_order` (`display_order`),
  CONSTRAINT `fk_app_category` FOREIGN KEY (`category_id`) REFERENCES `tbl_product_category` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_app_product` FOREIGN KEY (`product_id`) REFERENCES `tbl_product_items` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Product application examples';

DROP TABLE IF EXISTS `tbl_product_category`;
CREATE TABLE `tbl_product_category` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `category_name` varchar(255) NOT NULL COMMENT 'Category display name',
  `slug` varchar(255) DEFAULT NULL COMMENT 'URL-friendly identifier',
  `description` text DEFAULT NULL COMMENT 'Category description',
  `product_image` varchar(255) DEFAULT NULL COMMENT 'Category thumbnail image',
  `icon` varchar(100) DEFAULT NULL COMMENT 'Icon class for display',
  `display_order` int(11) DEFAULT 0 COMMENT 'Sort order',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '1=active, 0=inactive',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `is_active` (`is_active`),
  KEY `display_order` (`display_order`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Product categories';

DROP TABLE IF EXISTS `tbl_product_downloads`;
CREATE TABLE `tbl_product_downloads` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL COMMENT 'FK to tbl_product_items',
  `download_label` varchar(255) NOT NULL COMMENT 'Download button label',
  `download_type` varchar(50) DEFAULT 'pdf' COMMENT 'File type (pdf, cad, doc, etc.)',
  `file_url` varchar(500) NOT NULL COMMENT 'File URL or path',
  `file_size` varchar(50) DEFAULT NULL COMMENT 'File size display',
  `language` varchar(10) DEFAULT 'en' COMMENT 'File language code',
  `icon_class` varchar(100) DEFAULT 'fas fa-file-pdf' COMMENT 'Font Awesome icon class',
  `display_order` int(11) DEFAULT 0 COMMENT 'Sort order',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '1=active, 0=inactive',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`),
  KEY `is_active` (`is_active`),
  KEY `display_order` (`display_order`),
  CONSTRAINT `fk_download_product` FOREIGN KEY (`product_id`) REFERENCES `tbl_product_items` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Product downloadable files';

DROP TABLE IF EXISTS `tbl_product_items`;
CREATE TABLE `tbl_product_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_category` int(11) NOT NULL COMMENT 'FK to tbl_product_category',
  `product_type` int(11) DEFAULT NULL COMMENT 'FK to tbl_product_types',
  `product_name` varchar(255) NOT NULL COMMENT 'Product display name',
  `series_name` varchar(255) DEFAULT NULL COMMENT 'Product series name (e.g., SS2-P-1 series)',
  `sub_title` varchar(500) DEFAULT NULL COMMENT 'Product subtitle/tagline',
  `slug` varchar(255) DEFAULT NULL COMMENT 'URL-friendly identifier',
  `model_number` varchar(100) DEFAULT NULL COMMENT 'Model/SKU number',
  `description` text DEFAULT NULL COMMENT 'Product description',
  `short_description` varchar(500) DEFAULT NULL COMMENT 'Short summary',
  `product_image` varchar(255) DEFAULT NULL COMMENT 'Main product image',
  `dimensions_image` varchar(255) DEFAULT NULL COMMENT 'Dimension diagram image',
  `contact_configuration_image` varchar(255) DEFAULT NULL COMMENT 'Contact configuration image for models',
  `gallery_images` text DEFAULT NULL COMMENT 'JSON array of additional images',
  `features` text DEFAULT NULL COMMENT 'Line-separated features',
  `specifications` text DEFAULT NULL COMMENT 'Technical specifications',
  `operating_distances` text DEFAULT NULL COMMENT 'Operating distance specifications',
  `complied_standards` text DEFAULT NULL COMMENT 'Compliance and certification standards',
  `models_data` text DEFAULT NULL COMMENT 'JSON array of product models',
  `applications` text DEFAULT NULL COMMENT 'Use cases/applications',
  `applications_data` text DEFAULT NULL COMMENT 'JSON array of application examples',
  `related_products` text DEFAULT NULL COMMENT 'JSON array of related product IDs',
  `tags` varchar(500) DEFAULT NULL COMMENT 'Comma-separated tags',
  `video_url` varchar(255) DEFAULT NULL COMMENT 'Product video URL',
  `youtube_embed` varchar(255) DEFAULT NULL COMMENT 'YouTube embed ID',
  `brochure_pdf` varchar(255) DEFAULT NULL COMMENT 'Product brochure file',
  `manual_pdf` varchar(255) DEFAULT NULL COMMENT 'Product manual file',
  `datasheet_pdf` varchar(255) DEFAULT NULL COMMENT 'Datasheet file',
  `cad_files` text DEFAULT NULL COMMENT 'JSON array of CAD files',
  `downloads_data` text DEFAULT NULL COMMENT 'JSON array of downloadable files',
  `price` decimal(10,2) DEFAULT NULL COMMENT 'Product price',
  `currency` varchar(10) DEFAULT 'USD' COMMENT 'Price currency',
  `stock_status` varchar(50) DEFAULT 'in_stock' COMMENT 'Stock availability',
  `meta_title` varchar(255) DEFAULT NULL COMMENT 'SEO meta title',
  `meta_description` text DEFAULT NULL COMMENT 'SEO meta description',
  `meta_keywords` text DEFAULT NULL COMMENT 'SEO keywords',
  `display_order` int(11) DEFAULT 0 COMMENT 'Sort order within type',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '1=visible, 0=hidden',
  `is_featured` tinyint(1) DEFAULT 0 COMMENT '1=featured product',
  `is_new` tinyint(1) DEFAULT 0 COMMENT '1=new product',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_by` int(11) DEFAULT NULL COMMENT 'User ID who created',
  `updated_by` int(11) DEFAULT NULL COMMENT 'User ID who updated',
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `product_category` (`product_category`),
  KEY `product_type` (`product_type`),
  KEY `is_active` (`is_active`),
  KEY `is_featured` (`is_featured`),
  KEY `display_order` (`display_order`),
  KEY `idx_category_active` (`product_category`,`is_active`),
  KEY `idx_type_active` (`product_type`,`is_active`),
  KEY `idx_category_type_active` (`product_category`,`product_type`,`is_active`),
  CONSTRAINT `fk_item_category` FOREIGN KEY (`product_category`) REFERENCES `tbl_product_category` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_item_type` FOREIGN KEY (`product_type`) REFERENCES `tbl_product_types` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Individual product items';

