DROP VIEW IF EXISTS `v_active_products`;
select `pi`.`id` AS `id`,`pi`.`product_category` AS `product_category`,`pi`.`product_type` AS `product_type`,`pi`.`product_name` AS `product_name`,`pi`.`slug` AS `slug`,`pi`.`model_number` AS `model_number`,`pi`.`description` AS `description`,`pi`.`short_description` AS `short_description`,`pi`.`product_image` AS `product_image`,`pi`.`gallery_images` AS `gallery_images`,`pi`.`features` AS `features`,`pi`.`specifications` AS `specifications`,`pi`.`applications` AS `applications`,`pi`.`tags` AS `tags`,`pi`.`video_url` AS `video_url`,`pi`.`youtube_embed` AS `youtube_embed`,`pi`.`brochure_pdf` AS `brochure_pdf`,`pi`.`manual_pdf` AS `manual_pdf`,`pi`.`datasheet_pdf` AS `datasheet_pdf`,`pi`.`cad_files` AS `cad_files`,`pi`.`price` AS `price`,`pi`.`currency` AS `currency`,`pi`.`stock_status` AS `stock_status`,`pi`.`meta_title` AS `meta_title`,`pi`.`meta_description` AS `meta_description`,`pi`.`meta_keywords` AS `meta_keywords`,`pi`.`display_order` AS `display_order`,`pi`.`is_active` AS `is_active`,`pi`.`is_featured` AS `is_featured`,`pi`.`is_new` AS `is_new`,`pi`.`created_at` AS `created_at`,`pi`.`updated_at` AS `updated_at`,`pi`.`created_by` AS `created_by`,`pi`.`updated_by` AS `updated_by`,`pc`.`category_name` AS `category_name`,`pc`.`slug` AS `category_slug`,`pt`.`type_name` AS `type_name`,`pt`.`slug` AS `type_slug` from ((`lineseiki_db`.`tbl_product_items` `pi` left join `lineseiki_db`.`tbl_product_category` `pc` on(`pi`.`product_category` = `pc`.`id`)) left join `lineseiki_db`.`tbl_product_types` `pt` on(`pi`.`product_type` = `pt`.`id`)) where `pi`.`is_active` = 1 and `pc`.`is_active` = 1 order by `pc`.`display_order`,`pt`.`display_order`,`pi`.`display_order`;

DROP VIEW IF EXISTS `v_category_product_counts`;
select `pc`.`id` AS `id`,`pc`.`category_name` AS `category_name`,`pc`.`slug` AS `slug`,count(`pi`.`id`) AS `product_count` from (`lineseiki_db`.`tbl_product_category` `pc` left join `lineseiki_db`.`tbl_product_items` `pi` on(`pc`.`id` = `pi`.`product_category` and `pi`.`is_active` = 1)) where `pc`.`is_active` = 1 group by `pc`.`id`,`pc`.`category_name`,`pc`.`slug` order by `pc`.`display_order`;

DROP VIEW IF EXISTS `v_featured_products`;
select `pi`.`id` AS `id`,`pi`.`product_category` AS `product_category`,`pi`.`product_type` AS `product_type`,`pi`.`product_name` AS `product_name`,`pi`.`slug` AS `slug`,`pi`.`model_number` AS `model_number`,`pi`.`description` AS `description`,`pi`.`short_description` AS `short_description`,`pi`.`product_image` AS `product_image`,`pi`.`gallery_images` AS `gallery_images`,`pi`.`features` AS `features`,`pi`.`specifications` AS `specifications`,`pi`.`applications` AS `applications`,`pi`.`tags` AS `tags`,`pi`.`video_url` AS `video_url`,`pi`.`youtube_embed` AS `youtube_embed`,`pi`.`brochure_pdf` AS `brochure_pdf`,`pi`.`manual_pdf` AS `manual_pdf`,`pi`.`datasheet_pdf` AS `datasheet_pdf`,`pi`.`cad_files` AS `cad_files`,`pi`.`price` AS `price`,`pi`.`currency` AS `currency`,`pi`.`stock_status` AS `stock_status`,`pi`.`meta_title` AS `meta_title`,`pi`.`meta_description` AS `meta_description`,`pi`.`meta_keywords` AS `meta_keywords`,`pi`.`display_order` AS `display_order`,`pi`.`is_active` AS `is_active`,`pi`.`is_featured` AS `is_featured`,`pi`.`is_new` AS `is_new`,`pi`.`created_at` AS `created_at`,`pi`.`updated_at` AS `updated_at`,`pi`.`created_by` AS `created_by`,`pi`.`updated_by` AS `updated_by`,`pc`.`category_name` AS `category_name`,`pt`.`type_name` AS `type_name` from ((`lineseiki_db`.`tbl_product_items` `pi` left join `lineseiki_db`.`tbl_product_category` `pc` on(`pi`.`product_category` = `pc`.`id`)) left join `lineseiki_db`.`tbl_product_types` `pt` on(`pi`.`product_type` = `pt`.`id`)) where `pi`.`is_active` = 1 and `pi`.`is_featured` = 1 order by `pi`.`display_order`;













